INSERT INTO t_permission(name,code,type,parent_id,path,method,status,sort,create_time,update_time,del_flag) SELECT '流式调用智能体','ai:agent:stream:api','api',p.id,'/v1/agent-console/agents/by-code/{code}/stream','POST','active',0,NOW(),NOW(),0 FROM t_permission p WHERE p.code='ai:agent' AND p.del_flag=0 AND NOT EXISTS(SELECT 1 FROM t_permission WHERE code='ai:agent:stream:api' AND del_flag=0);
INSERT INTO t_permission(name,code,type,parent_id,path,method,status,sort,create_time,update_time,del_flag) SELECT '查询会话执行过程','ai:session:events:api','api',p.id,'/v1/agent-console/agents/{id}/sessions/{sessionId}/events','GET','active',0,NOW(),NOW(),0 FROM t_permission p WHERE p.code='ai:agent' AND p.del_flag=0 AND NOT EXISTS(SELECT 1 FROM t_permission WHERE code='ai:session:events:api' AND del_flag=0);
INSERT INTO t_role_permission(role_id,permission_id,create_time,update_time,del_flag) SELECT r.id,p.id,NOW(),NOW(),0 FROM t_role r CROSS JOIN t_permission p WHERE r.code='superAdmin' AND r.status='active' AND r.del_flag=0 AND p.code IN ('ai:agent:stream:api','ai:session:events:api') AND p.del_flag=0 AND NOT EXISTS(SELECT 1 FROM t_role_permission rp WHERE rp.role_id=r.id AND rp.permission_id=p.id AND rp.del_flag=0);
